a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: calibration_groups.R <pred.csv> <out> <times> [groups]");if(!requireNamespace("survival",quietly=TRUE)||!requireNamespace("ggplot2",quietly=TRUE))stop("Install survival and ggplot2");d<-read.csv(a[1],check.names=FALSE);out<-a[2];tt<-as.numeric(strsplit(a[3],",",TRUE)[[1]]);g<-if(length(a)>=4)as.integer(a[4])else 10L;dir.create(out,recursive=TRUE,showWarnings=FALSE);all<-list();for(t in tt){cols<-grep(paste0("__risk__",t,"$"),names(d),value=TRUE);for(n in cols){cuts<-unique(quantile(d[[n]],probs=seq(0,1,length.out=g+1),na.rm=TRUE));grp<-cut(d[[n]],cuts,include.lowest=TRUE,labels=FALSE);for(k in sort(unique(grp))){ii<-which(grp==k);sf<-survival::survfit(survival::Surv(Time,Event)~1,d[ii,]);s<-summary(sf,times=t,extend=TRUE);all[[length(all)+1]]<-data.frame(time=t,model=sub(paste0("__risk__",t,"$"),"",n),group=k,predicted=mean(d[[n]][ii]),observed=1-s$surv,n=length(ii))}}};z<-do.call(rbind,all);write.csv(z,file.path(out,"calibration_groups.csv"),row.names=FALSE);p<-ggplot2::ggplot(z,ggplot2::aes(predicted,observed,color=factor(time)))+ggplot2::geom_abline(linetype=2)+ggplot2::geom_line()+ggplot2::geom_point()+ggplot2::facet_wrap(~model)+ggplot2::coord_equal(xlim=c(0,1),ylim=c(0,1))+ggplot2::theme_classic()+ggplot2::labs(color="Horizon");ggplot2::ggsave(file.path(out,"calibration.pdf"),p,width=8,height=6)
